<?php if(!isset($manager,$user)){http_response_code(404);exit;}$accounts=$manager->query('SELECT id,username,role,active,created_at FROM admin_users ORDER BY id'); ?>
<section class="card"><h2>Add a staff account</h2><p class="help">Staff can manage bookings, calendar, prices, content and photos. Administrators also manage accounts, house settings, email, backups and launch approvals.</p><?php form_start('user_save','users');input('username','Username','','text',true,'minlength="3" maxlength="50" autocomplete="off"');input('password_new','Initial password (at least 16 characters)','','password',true,'minlength="16" maxlength="200" autocomplete="new-password"');select('role','Role',['staff'=>'Staff','admin'=>'Administrator']);checkbox('active','Account active',true);?><button>Create account</button></form></section>
<section class="card"><h2>Accounts</h2><?php foreach($accounts as $account):?><details><summary><?=ae($account['username'])?> · <?=ae($account['role'])?> · <?=$account['active']?'Active':'Inactive'?></summary><?php form_start('user_save','users',['id'=>$account['id']]);input('username','Username',$account['username'],'text',true,'minlength="3" maxlength="50"');select('role','Role',['staff'=>'Staff','admin'=>'Administrator'],$account['role']);if((int)$account['id']!==(int)$user['id'])input('password_new','New password (leave blank to keep)','','password',false,'minlength="16" maxlength="200" autocomplete="new-password"');checkbox('active','Account active',(bool)$account['active']);?><button>Save account</button></form></details><?php endforeach;?></section>
